#!/usr/bin/env tsx
/**
 * Keeps the GitHub issue forms in sync with the content.
 *
 *   npm run forms:sync    regenerate src/data/part-options.ts and .github/ISSUE_TEMPLATE/*
 *   npm run forms:check   fail (exit 1) if any of those files is out of date (runs in CI)
 *
 * Part options come from src/content/parts/*.yaml; every other field, label and option
 * comes from src/lib/contribution.ts, which the web form and the serverless function use
 * too. Never edit the generated files by hand.
 */
import { readdirSync, readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
import { parse, stringify } from 'yaml';

const check = process.argv.includes('--check');
const root = new URL('..', import.meta.url).pathname;
const stale: string[] = [];

/** Formats with the repo's Prettier config so generated files pass format:check. */
const pretty = (path: string, text: string) =>
  execFileSync('npx', ['prettier', '--stdin-filepath', path], {
    input: text,
    cwd: root,
  }).toString();

function emit(rel: string, text: string) {
  const path = join(root, rel);
  const formatted = pretty(path, text);
  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
  if (current === formatted) return;
  if (check) stale.push(rel);
  else {
    writeFileSync(path, formatted);
    console.log(`wrote ${rel}`);
  }
}

// 1. Part options, sorted by name, from the content files.
const partsDir = join(root, 'src/content/parts');
type PartRow = { id: string; name: string; system: string };
const parts: PartRow[] = readdirSync(partsDir)
  .filter((f: string) => /\.ya?ml$/.test(f))
  .map(
    (f) =>
      parse(readFileSync(join(partsDir, f), 'utf8')) as {
        id: string;
        name: string;
        system: string;
      },
  )
  .map(({ id, name, system }) => ({ id, name, system }))
  .sort((a, b) => a.name.localeCompare(b.name, 'en'));

emit(
  'src/data/part-options.ts',
  `// GENERATED by scripts/sync-issue-forms.ts from src/content/parts. Do not edit.
// Run \`npm run forms:sync\` after adding, renaming or removing a part.
export const PART_OPTIONS = ${JSON.stringify(parts, null, 2)} as const;
`,
);

// 2. Issue forms. Imported after step 1 so a fresh part list is picked up.
const c = await import('../src/lib/contribution.ts');
const { site, siteUrl } = await import('../src/site.config.ts');
const dir = '.github/ISSUE_TEMPLATE';
if (!check) mkdirSync(join(root, dir), { recursive: true });

const header =
  '# GENERATED by scripts/sync-issue-forms.ts from src/lib/contribution.ts. Do not edit.\n';

for (const [type, t] of Object.entries(c.CONTRIBUTION_TYPES) as [
  keyof typeof c.CONTRIBUTION_TYPES,
  (typeof c.CONTRIBUTION_TYPES)[keyof typeof c.CONTRIBUTION_TYPES],
][]) {
  const body: unknown[] = [
    {
      type: 'markdown',
      attributes: {
        value: `${t.blurb}\n\nNo GitHub account? Use the [web form](${siteUrl}/contribute/form?type=${type}) instead. Please read the [review rules](${siteUrl}/contribute#review).`,
      },
    },
  ];
  // GitHub's own title box replaces "summary"; credit comes from the GitHub account.
  for (const f of c.fieldsFor(type).filter((f) => f.id !== 'summary')) {
    const label = c.labelOf(f, type);
    const description = c.descriptionOf(f, type);
    const required = c.isRequired(f, type);
    const attrs: Record<string, unknown> = { label };
    if (description) attrs.description = description;
    if (f.kind === 'dropdown') {
      attrs.options = f.options();
      body.push({ type: 'dropdown', id: f.id, attributes: attrs, validations: { required } });
    } else if (f.kind === 'input') {
      if (f.placeholder) attrs.placeholder = f.placeholder;
      body.push({ type: 'input', id: f.id, attributes: attrs, validations: { required } });
    } else if (f.kind === 'textarea') {
      if (f.id === 'source')
        attrs.description = `${description} Drag a photo into this box to attach it.`;
      body.push({ type: 'textarea', id: f.id, attributes: attrs, validations: { required } });
    } else {
      body.push({
        type: 'checkboxes',
        id: f.id,
        attributes: { label, options: [{ label: f.text, required }] },
      });
    }
  }
  const form = {
    name: t.label,
    description: t.blurb,
    title: `[${t.short}] `,
    labels: c.TYPE_LABELS[type],
    body,
  };
  emit(`${dir}/${t.template}`, header + stringify(form, { lineWidth: 0 }));
}

emit(
  `${dir}/config.yml`,
  header +
    stringify({
      blank_issues_enabled: false,
      contact_links: [
        {
          name: 'No GitHub account? Use the web form',
          url: `${siteUrl}/contribute/form`,
          about: 'Same questions, no account needed.',
        },
        {
          name: 'Ask the community',
          url: `${siteUrl}/community`,
          about: `Questions and chat belong in the owner groups (Reddit, Discord, Facebook). ${site.shortName} isn’t a forum.`,
        },
      ],
    }),
);

if (stale.length) {
  console.error(
    `Out of date: ${stale.join(', ')}\nRun \`npm run forms:sync\` and commit the result.`,
  );
  process.exit(1);
}
if (check) console.log('Issue forms and part options are up to date.');
